  // ==========================================
  // TACTICAL SUITE: SECTORS, EVACUATION, MEASURE, ROSTER
  // ==========================================
  const sectorsGroup = new THREE.Group(); scene.add(sectorsGroup); sectorsGroup.visible = false;
  const evacGroup = new THREE.Group(); scene.add(evacGroup); evacGroup.visible = false;
  const measureGroup = new THREE.Group(); scene.add(measureGroup); measureGroup.visible = true;

  function getTacticalSector(item) {
    const z = typeof item.z === 'number' ? item.z : (item.p ? item.p[2] : 0);
    const d = (item.duty || '').toLowerCase();
    if (z < -135 || d.includes('helipad')) {
      return { id: 1, name: 'Sector 1: Helipad & Convoy', short: 'Sector 1', tag: 'SEC-1', color: '#0ea5e9', bg: '#f0f9ff', border: '#0284c7' };
    }
    if (z <= -48 || d.includes('gate') || d.includes('naka') || d.includes('perimeter') || d.includes('road')) {
      return { id: 2, name: 'Sector 2: Main Gate & Perimeter', short: 'Sector 2', tag: 'SEC-2', color: '#f59e0b', bg: '#fffbeb', border: '#d97706' };
    }
    return { id: 3, name: 'Sector 3: Auditorium & Stage', short: 'Sector 3', tag: 'SEC-3', color: '#10b981', bg: '#ecfdf5', border: '#059669' };
  }
  window.getTacticalSector = getTacticalSector;

  function makeSectorBadgeSprite(text, color) {
    const c = document.createElement('canvas');
    c.width = 512;
    c.height = 120;
    const ctx = c.getContext('2d');
    ctx.fillStyle = 'rgba(15, 23, 42, 0.88)';
    if (ctx.roundRect) {
      ctx.roundRect(8, 8, 496, 104, 18);
    } else {
      ctx.rect(8, 8, 496, 104);
    }
    ctx.fill();
    ctx.lineWidth = 5;
    ctx.strokeStyle = color;
    ctx.stroke();

    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 26px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, 256, 60);

    const tex = new THREE.CanvasTexture(c);
    tex.encoding = THREE.sRGBEncoding;
    const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false });
    const sprite = new THREE.Sprite(mat);
    sprite.scale.set(30, 7.5, 1);
    return sprite;
  }

  function makeBoundaryRibbon(zPos, colorHex) {
    const geom = new THREE.PlaneGeometry(280, 1.4);
    const mat = new THREE.MeshBasicMaterial({
      color: colorHex,
      side: THREE.DoubleSide,
      transparent: true,
      opacity: 0.70,
      depthWrite: false
    });
    const mesh = new THREE.Mesh(geom, mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.set(-20, 0.38, zPos);
    return mesh;
  }

  function build3DSectors() {
    sectorsGroup.clear();
    // Boundary ribbons
    sectorsGroup.add(makeBoundaryRibbon(-135, 0x0ea5e9));
    sectorsGroup.add(makeBoundaryRibbon(-48, 0xf59e0b));

    // Floating billboard badges
    const badge1 = makeSectorBadgeSprite('🛡️ SECTOR 1 · HELIPAD & CONVOY', '#0ea5e9');
    badge1.position.set(25, 12, -185);
    sectorsGroup.add(badge1);

    const badge2 = makeSectorBadgeSprite('🛡️ SECTOR 2 · MAIN GATE & PERIMETER', '#f59e0b');
    badge2.position.set(-13, 11, -92);
    sectorsGroup.add(badge2);

    const badge3 = makeSectorBadgeSprite('🛡️ SECTOR 3 · AUDITORIUM & VVIP STAGE', '#10b981');
    badge3.position.set(-38, 14, 5);
    sectorsGroup.add(badge3);
  }
  build3DSectors();

  function makeTubeRoute(points, colorHex) {
    const vPoints = points.map(p => new THREE.Vector3(p[0], p[1], p[2]));
    const curve = new THREE.CatmullRomCurve3(vPoints);
    const geom = new THREE.TubeGeometry(curve, 72, 0.52, 8, false);
    const mat = new THREE.MeshStandardMaterial({
      color: colorHex,
      emissive: colorHex,
      emissiveIntensity: 0.9,
      roughness: 0.25
    });
    return new THREE.Mesh(geom, mat);
  }

  function build3DEvacuationRoutes() {
    evacGroup.clear();
    // 1. Primary VVIP Corridor: Stage -> Gate -> Helipad
    const primaryPoints = [
      [-40, 1.35, 13],
      [-42, 1.35, -25],
      [-32, 1.35, -42],
      [-13, 1.35, -61],
      [-13, 1.35, -135],
      [10, 1.35, -178],
      [35, 1.35, -185]
    ];
    evacGroup.add(makeTubeRoute(primaryPoints, 0x10b981));

    // 2. Secondary Contingency Route: Stage Rear -> West Road -> Perimeter
    const contPoints = [
      [-25, 1.35, 38],
      [-65, 1.35, 35],
      [-80, 1.35, 0],
      [-85, 1.35, -45],
      [-95, 1.35, -115]
    ];
    evacGroup.add(makeTubeRoute(contPoints, 0xef4444));

    // 3. Medical Emergency Route: Central Lawn -> Main Gate -> NH-44
    const medPoints = [
      [10, 1.35, -10],
      [-5, 1.35, -40],
      [-13, 1.35, -61],
      [45, 1.35, -61]
    ];
    evacGroup.add(makeTubeRoute(medPoints, 0xf59e0b));
  }
  build3DEvacuationRoutes();

  // Sector Counts Helper
  function updateSectorLegendCounts() {
    if (typeof depItems === 'undefined' || !Array.isArray(depItems)) return;
    let s1 = 0, s2 = 0, s3 = 0;
    depItems.forEach(item => {
      const sec = getTacticalSector(item);
      if (sec.id === 1) s1++;
      else if (sec.id === 2) s2++;
      else s3++;
    });
    const c1 = root.querySelector('#legend-count-sec1');
    const c2 = root.querySelector('#legend-count-sec2');
    const c3 = root.querySelector('#legend-count-sec3');
    if (c1) c1.textContent = s1 + ' deployed posts';
    if (c2) c2.textContent = s2 + ' deployed posts';
    if (c3) c3.textContent = s3 + ' deployed posts';
  }

  // Header Toggle Buttons Wiring
  const sectorsBtn = root.querySelector('#gms-sectors-btn');
  const sectorsLegend = root.querySelector('#gms-sectors-legend');
  const sectorsClose = root.querySelector('#sectors-legend-close');
  if (sectorsBtn) {
    sectorsBtn.addEventListener('click', () => {
      sectorsGroup.visible = !sectorsGroup.visible;
      sectorsBtn.classList.toggle('active', sectorsGroup.visible);
      if (sectorsLegend) sectorsLegend.style.display = sectorsGroup.visible ? 'block' : 'none';
      if (sectorsGroup.visible) updateSectorLegendCounts();
      draw();
    });
  }
  if (sectorsClose) {
    sectorsClose.addEventListener('click', () => {
      sectorsGroup.visible = false;
      if (sectorsBtn) sectorsBtn.classList.remove('active');
      if (sectorsLegend) sectorsLegend.style.display = 'none';
      draw();
    });
  }

  const evacBtn = root.querySelector('#gms-evac-btn');
  const evacLegend = root.querySelector('#gms-evac-legend');
  const evacClose = root.querySelector('#evac-legend-close');
  if (evacBtn) {
    evacBtn.addEventListener('click', () => {
      evacGroup.visible = !evacGroup.visible;
      evacBtn.classList.toggle('active', evacGroup.visible);
      if (evacLegend) evacLegend.style.display = evacGroup.visible ? 'block' : 'none';
      draw();
    });
  }
  if (evacClose) {
    evacClose.addEventListener('click', () => {
      evacGroup.visible = false;
      if (evacBtn) evacBtn.classList.remove('active');
      if (evacLegend) evacLegend.style.display = 'none';
      draw();
    });
  }

  // ==========================================
  // VIRTUAL 3D MEASURING TAPE
  // ==========================================
  let measureActive = false;
  let measurePoints = [];
  let measureTempLine = null;
  let measurePermLine = null;
  let pinA = null;
  let pinB = null;

  function makeMeasurePin(pos, colorHex) {
    const grp = new THREE.Group();
    // Sphere
    const sph = new THREE.Mesh(
      new THREE.SphereGeometry(0.5, 16, 16),
      new THREE.MeshStandardMaterial({ color: colorHex, emissive: colorHex, emissiveIntensity: 1.0 })
    );
    sph.position.set(0, 1.8, 0);
    grp.add(sph);

    // Pointer Cone
    const cone = new THREE.Mesh(
      new THREE.ConeGeometry(0.35, 1.6, 16),
      new THREE.MeshStandardMaterial({ color: colorHex, emissive: colorHex, emissiveIntensity: 0.6 })
    );
    cone.position.set(0, 0.8, 0);
    cone.rotation.x = Math.PI;
    grp.add(cone);

    // Ground Ring
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(0.6, 0.9, 24),
      new THREE.MeshBasicMaterial({ color: colorHex, side: THREE.DoubleSide })
    );
    ring.rotation.x = -Math.PI / 2;
    ring.position.set(0, 0.05, 0);
    grp.add(ring);

    grp.position.copy(pos);
    return grp;
  }

  function clearMeasurement() {
    measurePoints = [];
    if (pinA) { measureGroup.remove(pinA); pinA = null; }
    if (pinB) { measureGroup.remove(pinB); pinB = null; }
    if (measureTempLine) { measureGroup.remove(measureTempLine); measureTempLine = null; }
    if (measurePermLine) { measureGroup.remove(measurePermLine); measurePermLine = null; }
    const hint = root.querySelector('#measure-step-hint');
    if (hint) {
      hint.style.display = 'block';
      hint.innerHTML = 'Click on ground or building for <b>Point A</b>';
    }
    const statsRow = root.querySelector('#measure-stats-row');
    if (statsRow) statsRow.style.display = 'none';
    draw();
  }

  const measureBtn = root.querySelector('#gms-measure-btn');
  const measureHud = root.querySelector('#gms-measure-hud');
  const measureClose = root.querySelector('#measure-hud-close');
  const measureClear = root.querySelector('#measure-clear-btn');

  function toggleMeasureTool() {
    measureActive = !measureActive;
    if (measureBtn) measureBtn.classList.toggle('active', measureActive);
    if (measureHud) measureHud.style.display = measureActive ? 'block' : 'none';
    host.style.cursor = measureActive ? 'crosshair' : '';
    if (!measureActive) {
      clearMeasurement();
    }
  }

  if (measureBtn) measureBtn.addEventListener('click', toggleMeasureTool);
  if (measureClose) measureClose.addEventListener('click', toggleMeasureTool);
  if (measureClear) measureClear.addEventListener('click', clearMeasurement);

  // Measure Raycast Clicks
  host.addEventListener('pointerdown', (e) => {
    if (!measureActive || e.button !== 0) return;
    const rect = host.getBoundingClientRect();
    const mouseX = ((e.clientX - rect.left) / rect.width) * 2 - 1;
    const mouseY = -((e.clientY - rect.top) / rect.height) * 2 + 1;

    const r = new THREE.Raycaster();
    r.setFromCamera(new THREE.Vector2(mouseX, mouseY), camera);
    const intersects = r.intersectObjects(scene.children, true);
    const valid = intersects.find(it => {
      let cur = it.object;
      while (cur) {
        if (cur === measureGroup || cur === sectorsGroup || cur === evacGroup) return false;
        cur = cur.parent;
      }
      return true;
    });

    if (!valid) return;
    const pt = valid.point.clone();

    if (measurePoints.length === 0) {
      measurePoints.push(pt);
      pinA = makeMeasurePin(pt, 0xf59e0b);
      measureGroup.add(pinA);
      const hint = root.querySelector('#measure-step-hint');
      if (hint) hint.innerHTML = 'Point A set! Move mouse and click to place <b>Point B</b>';
      draw();
    } else if (measurePoints.length === 1) {
      measurePoints.push(pt);
      pinB = makeMeasurePin(pt, 0x0ea5e9);
      measureGroup.add(pinB);

      // Remove temporary line
      if (measureTempLine) { measureGroup.remove(measureTempLine); measureTempLine = null; }

      // Permanent Laser Tube
      const p1 = measurePoints[0], p2 = measurePoints[1];
      const curve = new THREE.LineCurve3(p1.clone().add(new THREE.Vector3(0, 0.4, 0)), p2.clone().add(new THREE.Vector3(0, 0.4, 0)));
      const tubeGeom = new THREE.TubeGeometry(curve, 16, 0.22, 8, false);
      measurePermLine = new THREE.Mesh(tubeGeom, new THREE.MeshBasicMaterial({ color: 0x38bdf8 }));
      measureGroup.add(measurePermLine);

      // Calculations
      const d3d = p1.distanceTo(p2);
      const dGround = Math.hypot(p2.x - p1.x, p2.z - p1.z);
      const dHeight = Math.abs(p2.y - p1.y);
      const walkTime = Math.round(dGround / 1.25);

      const hint = root.querySelector('#measure-step-hint');
      if (hint) hint.style.display = 'none';

      const statsRow = root.querySelector('#measure-stats-row');
      if (statsRow) statsRow.style.display = 'grid';

      const el3d = root.querySelector('#stat-dist-3d');
      const elGround = root.querySelector('#stat-dist-ground');
      const elHeight = root.querySelector('#stat-dist-height');
      const elWalk = root.querySelector('#stat-dist-walk');

      if (el3d) el3d.textContent = d3d.toFixed(1) + ' m';
      if (elGround) elGround.textContent = dGround.toFixed(1) + ' m';
      if (elHeight) elHeight.textContent = dHeight.toFixed(1) + ' m';
      if (elWalk) elWalk.textContent = (walkTime > 60 ? Math.floor(walkTime / 60) + 'm ' + (walkTime % 60) + 's' : walkTime + 's');

      draw();
    }
  });

  // Dynamic live measuring line on mousemove
  host.addEventListener('pointermove', (e) => {
    if (!measureActive || measurePoints.length !== 1) return;
    const rect = host.getBoundingClientRect();
    const mouseX = ((e.clientX - rect.left) / rect.width) * 2 - 1;
    const mouseY = -((e.clientY - rect.top) / rect.height) * 2 + 1;

    const r = new THREE.Raycaster();
    r.setFromCamera(new THREE.Vector2(mouseX, mouseY), camera);
    const intersects = r.intersectObjects(scene.children, true);
    const valid = intersects.find(it => {
      let cur = it.object;
      while (cur) {
        if (cur === measureGroup || cur === sectorsGroup || cur === evacGroup) return false;
        cur = cur.parent;
      }
      return true;
    });

    if (!valid) return;
    const pt = valid.point.clone();
    const p1 = measurePoints[0];

    if (measureTempLine) measureGroup.remove(measureTempLine);
    const lineGeom = new THREE.BufferGeometry().setFromPoints([
      p1.clone().add(new THREE.Vector3(0, 0.4, 0)),
      pt.clone().add(new THREE.Vector3(0, 0.4, 0))
    ]);
    measureTempLine = new THREE.Line(lineGeom, new THREE.LineDashedMaterial({ color: 0x38bdf8, dashSize: 1, gapSize: 0.5 }));
    measureTempLine.computeLineDistances();
    measureGroup.add(measureTempLine);

    const dLive = p1.distanceTo(pt);
    const hint = root.querySelector('#measure-step-hint');
    if (hint) hint.innerHTML = 'Distance to cursor: <b style="color:#38bdf8;font-size:14px;">' + dLive.toFixed(1) + ' m</b> · Click to anchor Point B';
    draw();
  });

  // ==========================================
  // DUTY ROSTER MODAL, CSV EXPORT & PRINT
  // ==========================================
  const rosterModal = root.querySelector('#gms-roster-modal');
  const rosterBtn = root.querySelector('#gms-roster-btn');
  const rosterClose = root.querySelector('#roster-close-btn');
  const rosterPrint = root.querySelector('#roster-print-btn');
  const rosterCsv = root.querySelector('#roster-csv-btn');
  const rosterSearch = root.querySelector('#roster-search-input');
  const rosterSector = root.querySelector('#roster-sector-filter');
  const rosterType = root.querySelector('#roster-type-filter');
  const rosterTbody = root.querySelector('#roster-tbody');
  const rosterEmpty = root.querySelector('#roster-empty-state');

  function openDutyRoster() {
    if (!rosterModal) return;
    renderDutyRoster();
    rosterModal.style.display = 'flex';
  }

  function closeDutyRoster() {
    if (!rosterModal) return;
    rosterModal.style.display = 'none';
  }

  if (rosterBtn) rosterBtn.addEventListener('click', openDutyRoster);
  if (rosterClose) rosterClose.addEventListener('click', closeDutyRoster);
  if (rosterModal) {
    rosterModal.addEventListener('click', (e) => {
      if (e.target === rosterModal) closeDutyRoster();
    });
  }

  function renderDutyRoster() {
    if (typeof depItems === 'undefined' || !Array.isArray(depItems)) return;
    const items = depItems;
    const q = (rosterSearch ? rosterSearch.value : '').trim().toLowerCase();
    const secFilter = rosterSector ? rosterSector.value : 'all';
    const typeFilter = rosterType ? rosterType.value : 'all';

    let s1 = 0, s2 = 0, s3 = 0, offCount = 0, equipCount = 0;

    const filtered = items.filter(it => {
      const sec = getTacticalSector(it);
      if (sec.id === 1) s1++;
      else if (sec.id === 2) s2++;
      else s3++;

      const isOfficer = ['officer', 'armed_officer', '_dummy'].includes(it.kind);
      if (isOfficer) offCount++; else equipCount++;

      // Sector Filter
      if (secFilter !== 'all' && String(sec.id) !== secFilter) return false;

      // Type Filter
      if (typeFilter === 'officers' && !isOfficer) return false;
      if (typeFilter === 'vehicles' && !['qrt', 'ambulance', 'firebrigade', 'parking'].includes(it.kind)) return false;
      if (typeFilter === 'scanners' && !['xray', 'dfmd', 'hhmd'].includes(it.kind)) return false;
      if (typeFilter === 'security' && !['barricade', 'cctv', 'binocular', 'radio', 'cone', 'light', 'qbelt'].includes(it.kind)) return false;

      // Search Query
      if (q) {
        const text = [it.name || '', it.duty || '', it.belt || '', it.mobile || '', sec.name, it.kind || ''].join(' ').toLowerCase();
        if (!text.includes(q)) return false;
      }
      return true;
    });

    // Update Metrics
    const cTotal = root.querySelector('#roster-count-total');
    const cS1 = root.querySelector('#roster-count-sec1');
    const cS2 = root.querySelector('#roster-count-sec2');
    const cS3 = root.querySelector('#roster-count-sec3');
    const cOff = root.querySelector('#roster-count-officers');
    const cEquip = root.querySelector('#roster-count-equip');

    if (cTotal) cTotal.textContent = items.length;
    if (cS1) cS1.textContent = s1;
    if (cS2) cS2.textContent = s2;
    if (cS3) cS3.textContent = s3;
    if (cOff) cOff.textContent = offCount;
    if (cEquip) cEquip.textContent = equipCount;

    if (!rosterTbody) return;
    rosterTbody.replaceChildren();

    if (filtered.length === 0) {
      if (rosterEmpty) rosterEmpty.style.display = 'block';
      return;
    }
    if (rosterEmpty) rosterEmpty.style.display = 'none';

    filtered.forEach((it, idx) => {
      const sec = getTacticalSector(it);
      const tr = document.createElement('tr');

      const x = typeof it.x === 'number' ? it.x.toFixed(1) : (it.p ? it.p[0].toFixed(1) : '0');
      const z = typeof it.z === 'number' ? it.z.toFixed(1) : (it.p ? it.p[2].toFixed(1) : '0');
      const symbol = (typeof depSymbols !== 'undefined' && depSymbols[it.kind]) ? depSymbols[it.kind] : '👮';

      tr.innerHTML = `
        <td style="font-weight:600;color:#64748b;">${idx + 1}</td>
        <td><b>${it.name || 'Post'}</b></td>
        <td>${it.duty || 'General Duty'}</td>
        <td><span class="roster-sector-tag" style="background:${sec.bg};color:${sec.color};border:1px solid ${sec.border};">${sec.tag}: ${sec.short}</span></td>
        <td><code>${it.belt || '—'}</code></td>
        <td>${it.mobile || '—'}</td>
        <td><span>${symbol} ${it.kind || 'post'}</span></td>
        <td style="font-size:11px;color:#64748b;">X: ${x}, Z: ${z}</td>
        <td class="roster-col-action"><button type="button" class="roster-btn-jump" data-id="${it.id}">Jump ➔</button></td>
      `;

      tr.querySelector('.roster-btn-jump').addEventListener('click', () => {
        closeDutyRoster();
        if (typeof depChoose === 'function') depChoose(it.id, true);
      });

      rosterTbody.appendChild(tr);
    });
  }

  if (rosterSearch) rosterSearch.addEventListener('input', renderDutyRoster);
  if (rosterSector) rosterSector.addEventListener('change', renderDutyRoster);
  if (rosterType) rosterType.addEventListener('change', renderDutyRoster);

  // Print Action
  if (rosterPrint) {
    rosterPrint.addEventListener('click', () => {
      window.print();
    });
  }

  // Export CSV Action
  if (rosterCsv) {
    rosterCsv.addEventListener('click', () => {
      if (typeof depItems === 'undefined' || !Array.isArray(depItems)) return;
      const headers = ['S.No', 'Officer / Post Name', 'Duty Place / Designation', 'Tactical Sector', 'Belt Number', 'Contact Mobile', 'Deployment Type', 'Coord X', 'Coord Z'];
      const rows = [headers];

      depItems.forEach((it, idx) => {
        const sec = getTacticalSector(it);
        const x = typeof it.x === 'number' ? it.x.toFixed(2) : (it.p ? it.p[0].toFixed(2) : '0');
        const z = typeof it.z === 'number' ? it.z.toFixed(2) : (it.p ? it.p[2].toFixed(2) : '0');
        rows.push([
          idx + 1,
          '"' + (it.name || '').replace(/"/g, '""') + '"',
          '"' + (it.duty || '').replace(/"/g, '""') + '"',
          '"' + sec.name + '"',
          '"' + (it.belt || '').replace(/"/g, '""') + '"',
          '"' + (it.mobile || '').replace(/"/g, '""') + '"',
          '"' + (it.kind || '') + '"',
          x,
          z
        ]);
      });

      const csvContent = '\uFEFF' + rows.map(r => r.join(',')).join('\r\n');
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'police-duty-roster-79th-samagam.csv';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    });
  }

var vvipSavedView = null;
