const depInitialPlan = (typeof window !== 'undefined' && window.__DEP_INITIAL_PLAN__) ? window.__DEP_INITIAL_PLAN__ : null;
const depTypes=Object.keys(depSymbols),depStorage='gyan-mansarovar-duty-v1';







