  const a=points[i-1],b=points[i],c=points[i+1],la=Math.hypot(...b.map((v,k)=>v-a[k])),lb=Math.hypot(...c.map((v,k)=>v-b[k])),trim=Math.min(radius,la*.25,lb*.25);
